pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Roulette c;

    function setUp() public {
        vm.deal(address(this), 10 ether);
        c = new Roulette{value: 10 ether}();
    }

    function _run(uint256 salt) internal {
        vm.assume(salt <= block.timestamp);
        uint256 t0;
        try c.pastBlockTime() returns (uint256 __r) { t0 = __r; } catch { return; }
        bool ok0;
        try c.pastBlockTime() returns (uint v0) { ok0 = (v0 == t0); } catch { ok0 = false; }
        bool ok1;
        uint t1;
        try c.pastBlockTime() returns (uint v1) { ok1 = true; t1 = v1; } catch { ok1 = false; }
        assertTrue(ok0 && ok1 && t1 >= t0 && t1 <= block.timestamp);
    }

    function testFuzz_run(uint256 salt) public {
        _run(salt);
    }

    receive() external payable {}
}
